pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes4 interfaceId) public {
        // The reference implements supportsInterface as:
        //   interfaceId == type(IAccessControl).interfaceId || super.supportsInterface(interfaceId)
        // The buggy version only does super.supportsInterface(interfaceId).
        // The property holds for reference: supportsInterface(interfaceId) equals that logical OR.
        bool expected = interfaceId == 0x7965db0b || c.supportsInterface(interfaceId);
        // Note: The above c.supportsInterface on reference already returns the correct value,
        // but we cannot call the reference version after deploying the buggy one in the same test.
        // Instead, we directly compute the expected value using the known IAccessControl interface ID
        // and a call to the parent ERC165 via an internal helper. However, we cannot access ERC165
        // directly from C. The only public way is supportsInterface itself, which would recurse.
        // Alternatively, we can rely on the known constant: type(IAccessControl).interfaceId is 0x7965db0b.
        // ERC165's supportsInterface returns interfaceId == 0x01ffc9a7 (type(IERC165).interfaceId).
        // For any other interfaceId, ERC165 returns false, so the reference returns true only for IAccessControl,
        // and the bug returns false for IAccessControl but true for IERC165.
        // The property: c.supportsInterface(interfaceId) == (interfaceId == 0x7965db0b || interfaceId == 0x01ffc9a7).
        bool result = c.supportsInterface(interfaceId);
        assertTrue(result == (interfaceId == 0x7965db0b || interfaceId == 0x01ffc9a7));
    }
}

