contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
    }

    function testFuzz_property(bytes4 interfaceId) public {
        // The reference implementation returns true for type(IERC165).interfaceId
        // because of the 'super.supportsInterface(interfaceId)' fallback.
        // The buggy version returns true only for type(IAccessControl).interfaceId.
        // Rule: for any interfaceId, if the result is true then it must also be true
        // for type(IAccessControl).interfaceId OR the context must satisfy the ERC165 fallback;
        // equivalently, the reference always returns true for the ERC165 interface itself.
        // We check the simpler invariant: supportsInterface(type(IERC165).interfaceId) is always true.
        bool result = c.supportsInterface(interfaceId);
        bool erc165Result = c.supportsInterface(type(IERC165).interfaceId);
        assertTrue(erc165Result && (result == (interfaceId == type(IAccessControl).interfaceId || erc165Result)));
        // This assertion simplifies to: erc165Result must be true (reference holds, bug fails when
        // the fuzzer picks type(IERC165).interfaceId and the bug returns false).
    }
}

