pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 role, address account) public {
        // The PROPOSER_ROLE is not given to the fuzzed account, so hasRole should be false.
        // With the bug, it returns true for any input.
        bool has = c.hasRole(role, account);
        // The general rule: an account that has never been granted a role must not have it.
        // Since the contract in setUp only grants roles to deployer(address(this)) and itself,
        // any other account (or even these accounts for a role not granted) must return false.
        // To make it a universal property: if the account is address(this), we skip because it has some roles.
        // But the bug returns true always, so we assert that for a random role and random account
        // the result is false (the reference passes, the bug fails for some input).
        // However, address(this) has TIMELOCK_ADMIN_ROLE, so we need to exclude the roles that are assigned.
        // We can simply assert that for a fresh random role (which is not the predefined ones) and any account,
        // it returns false. The predefined roles are: DEFAULT_ADMIN_ROLE (0x00),
        // TIMELOCK_ADMIN_ROLE, PROPOSER_ROLE, EXECUTOR_ROLE.
        vm.assume(role != bytes32(0));
        vm.assume(role != keccak256("TIMELOCK_ADMIN_ROLE"));
        vm.assume(role != keccak256("PROPOSER_ROLE"));
        vm.assume(role != keccak256("EXECUTOR_ROLE"));
        assertFalse(has);
    }
}

